  1	//! Device-local first ingress evidence. No payload or replicated metadata lives here.
  2	use super::*;
  3	use crate::eventlog::repository::EventDomainId;
  4	use crate::storage::profile::manifest;
  5	use rusqlite::{OptionalExtension, params};
  6	
  7	/// The authenticated immediate peer category at the first retained network ingress.
  8	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
  9	#[serde(rename_all = "snake_case")]
 10	pub enum ReceivedVia {
 11	    Sender,
 12	    Member,
 13	    PostOffice,
 14	    LinkedDevice,
 15	}
 16	impl ReceivedVia {
 17	    fn tag(self) -> i64 {
 18	        match self {
 19	            Self::Sender => 1,
 20	            Self::Member => 2,
 21	            Self::PostOffice => 3,
 22	            Self::LinkedDevice => 4,
 23	        }
 24	    }
 25	    fn from_tag(tag: i64) -> Result<Self, LogError> {
 26	        match tag {
 27	            1 => Ok(Self::Sender),
 28	            2 => Ok(Self::Member),
 29	            3 => Ok(Self::PostOffice),
 30	            4 => Ok(Self::LinkedDevice),
 31	            _ => Err(invalid("invalid ingress origin")),
 32	        }
 33	    }
 34	}
 35	
 36	pub(crate) struct IngressOrigin {
 37	    pub via: ReceivedVia,
 38	    pub peer_device: String,
 39	}
 40	
 41	const SCHEMA: &str = "
 42	CREATE TABLE pending_ingress_origins(account BLOB NOT NULL CHECK(length(account)=32), domain BLOB NOT NULL CHECK(length(domain)=16), event_id BLOB NOT NULL CHECK(length(event_id)=32), conversation BLOB NOT NULL CHECK(length(conversation)=32), via INTEGER NOT NULL CHECK(via BETWEEN 1 AND 4), peer_device TEXT NOT NULL CHECK(length(peer_device)=32), PRIMARY KEY(account,domain,event_id), FOREIGN KEY(domain,event_id) REFERENCES retained_events(domain,id) ON DELETE CASCADE);
 43	CREATE INDEX pending_ingress_source ON pending_ingress_origins(account,event_id,domain);
 44	CREATE TABLE transcript_ingress_origins(ordinal INTEGER PRIMARY KEY REFERENCES transcript_rows(ordinal) ON DELETE CASCADE, account BLOB NOT NULL CHECK(length(account)=32), via INTEGER NOT NULL CHECK(via BETWEEN 1 AND 4), peer_device TEXT NOT NULL CHECK(length(peer_device)=32));
 45	";
 46	
 47	pub(super) fn initialize_on(c: &Connection) -> Result<(), LogError> {
 48	    let present: i64 = c.query_row("SELECT count(*) FROM sqlite_master WHERE name IN ('pending_ingress_origins','pending_ingress_source','transcript_ingress_origins')", [], |r| r.get(0))?;
 49	    if present == 0 {
 50	        c.execute_batch(SCHEMA)?;
 51	    } else if present != 3 {
 52	        return Err(invalid("incomplete ingress origin schema"));
 53	    }
 54	    manifest::validate_ddl(c, SCHEMA)
 55	}
 56	
 57	impl ReceptionEffects {
 58	    /// The caller holds the raw append transaction. Never reacquire the database.
 59	    pub(crate) fn record_origin_on(
 60	        &self,
 61	        c: &Connection,
 62	        domain: EventDomainId,
 63	        event: &Event,
 64	        origin: &IngressOrigin,
 65	    ) -> Result<(), LogError> {
 66	        self.state_on(c)?;
 67	        if origin.peer_device.len() != 32
 68	            || !origin.peer_device.bytes().all(|b| b.is_ascii_hexdigit())
 69	        {
 70	            return Err(invalid("invalid ingress peer device"));
 71	        }
 72	        c.execute("INSERT INTO pending_ingress_origins(account,domain,event_id,conversation,via,peer_device) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(account,domain,event_id) DO NOTHING", params![self.account.as_slice(),domain.0.as_slice(),event.id.as_bytes().as_slice(),event.conversation_id.as_bytes().as_slice(),origin.via.tag(),origin.peer_device])?;
 73	        Ok(())
 74	    }
 75	
 76	    pub(crate) fn received_via(
 77	        &self,
 78	        conversation: ConversationId,
 79	        id: EventId,
 80	    ) -> Result<Option<ReceivedVia>, LogError> {
 81	        self.profile.database().read(|c| {
 82	            self.state_on(c)?;
 83	            // Select the first source row BEFORE joining evidence. An unknown old
 84	            // alias must not acquire a later alias's known ingress.
 85	            let tag: Option<Option<i64>> = c.query_row("SELECT o.via FROM transcript_rows t LEFT JOIN transcript_ingress_origins o ON o.ordinal=t.ordinal AND o.account=?1 WHERE t.ordinal=(SELECT MIN(ordinal) FROM (SELECT MIN(ordinal) AS ordinal FROM transcript_rows WHERE kind=2 AND conversation=?2 AND row_key=?3 UNION ALL SELECT MIN(ordinal) FROM transcript_rows WHERE kind=3 AND conversation=?2 AND row_key=?3 UNION ALL SELECT MIN(ordinal) FROM transcript_rows WHERE kind=2 AND conversation=?2 AND logical_id=?3 UNION ALL SELECT MIN(ordinal) FROM transcript_rows WHERE kind=3 AND conversation=?2 AND logical_id=?3))", params![self.account.as_slice(),conversation.as_bytes().as_slice(),id.as_bytes().as_slice()], |r| r.get(0)).optional()?;
 86	            tag.flatten().map(ReceivedVia::from_tag).transpose()
 87	        })
 88	    }
 89	
 90	    /// File identity bundles already bound their alias count and signatures.
 91	    /// Inspect only those exact row keys; an unknown first alias stays unknown.
 92	    pub(crate) fn received_file_via(
 93	        &self,
 94	        conversation: ConversationId,
 95	        raw: EventId,
 96	        aliases: &[EventId],
 97	    ) -> Result<Option<ReceivedVia>, LogError> {
 98	        self.profile.database().read(|c| {
 99	            self.state_on(c)?;
100	            file_origin_on(c, &self.account, conversation, raw, aliases)
101	        })
102	    }
103	}
104	
105	fn file_origin_on(
106	    c: &Connection,
107	    account: &[u8; 32],
108	    conversation: ConversationId,
109	    raw: EventId,
110	    aliases: &[EventId],
111	) -> Result<Option<ReceivedVia>, LogError> {
112	    let mut first: Option<i64> = None;
113	    let mut statement = c.prepare_cached(
114	        "SELECT ordinal FROM transcript_rows WHERE kind=3 AND conversation=?1 AND row_key=?2",
115	    )?;
116	    for id in aliases.iter().chain(std::iter::once(&raw)) {
117	        let ordinal: Option<i64> = statement
118	            .query_row(
119	                params![conversation.as_bytes().as_slice(), id.as_bytes().as_slice()],
120	                |r| r.get(0),
121	            )
122	            .optional()?;
123	        if let Some(ordinal) = ordinal {
124	            first = Some(first.map_or(ordinal, |previous| previous.min(ordinal)));
125	        }
126	    }
127	    let Some(first) = first else { return Ok(None) };
128	    let tag: Option<i64> = c
129	        .query_row(
130	            "SELECT via FROM transcript_ingress_origins WHERE ordinal=?1 AND account=?2",
131	            params![first, account.as_slice()],
132	            |r| r.get(0),
133	        )
134	        .optional()?;
135	    tag.map(ReceivedVia::from_tag).transpose()
136	}
