 30	fn ensure_stream_on(c: &Connection, account: &[u8; 32]) -> Result<(), LogError> {
 31	    let present: bool = c.query_row(
 32	        "SELECT EXISTS(SELECT 1 FROM reception_stream WHERE account=?1)",
 33	        [account.as_slice()],
 34	        |row| row.get(0),
 35	    )?;
 36	    if !present {
 37	        let mut epoch = [0; 16];
 38	        OsRng.fill_bytes(&mut epoch);
 39	        c.execute(
 40	            "INSERT INTO reception_stream VALUES(?1,?2,0,0)",
 41	            params![account.as_slice(), epoch.as_slice()],
 42	        )?;
 43	    }
 44	    Ok(())
 45	}
 46	pub(super) fn state_on(c: &Connection, account: &[u8; 32]) -> Result<StreamState, LogError> {
 47	    if active_account_on(c)? != *account {
 48	        return Err(LogError::StaleCursor);
 49	    }
 50	    let mut statement = c.prepare(
 51	        "SELECT epoch,high_water,retired_through FROM reception_stream WHERE account=?1",
 52	    )?;
 53	    let mut rows = statement.query([account.as_slice()])?;
 54	    let row = rows
 55	        .next()?
 56	        .ok_or_else(|| invalid("missing reception stream owner"))?;
 57	    Ok(StreamState {
 58	        head: ReceptionCursor {
 59	            epoch: blob(row, 0)?,
 60	            sequence: natural(row.get(1)?)?,
 61	        },
 62	        retired: natural(row.get(2)?)?,
 63	    })
 64	}
