 22	async fn file_manifest_requester_reception(retained: bool) {
 23	    let ad = tempfile::tempdir().unwrap();
 24	    let bd = tempfile::tempdir().unwrap();
 25	    let alice = DeviceIdentity::generate();
 26	    let bob = DeviceIdentity::generate();
 27	    let aa = Account::generate();
 28	    let bob_account = Account::generate();
 29	    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
 30	    let ap = Announce::new_with_account(&alice, &aa, "Alice", 9);
 31	    let bp = Announce::new_with_account(
 32	        &bob,
 33	        &bob_account,
 34	        "Bob",
 35	        listener.local_addr().unwrap().port(),
 36	    );
 37	    // Keep production manual file consent. No accept-loop delivery worker or
 38	    // verified-peer pull loop may import the reply on the requester's behalf.
 39	    let (a, mut incoming, _) = super::test_support::node_with_files(ad.path(), alice, aa, &bp);
 40	    let (b, _, mut offers) = super::test_support::node_with_files(bd.path(), bob, bob_account, &ap);
 41	    let path = ad.path().join("pending-file.txt");
 42	    std::fs::write(&path, b"bytes still awaiting manual consent").unwrap();
 43	    let (card, _) = a
 44	        .enqueue_file_to_account(&b.account_id(), &path, crate::file::FileKind::File)
 45	        .await
 46	        .unwrap();
 47	    let reply = b
 48	        .enqueue_to_account(&a.account_id(), b"reply pulled by a file requester", None)
 49	        .await
 50	        .unwrap();
 51	    let original = {
 52	        let delivery = b.delivery.lock().unwrap();
 53	        let pending = delivery.message(reply).unwrap();
 54	        assert_eq!(pending.destinations.len(), 1);
 55	        pending.destinations[0].event.clone()
 56	    };
 57	    assert!(a.log.lock().unwrap().get(&original.id).unwrap().is_none());
 58	    assert!(incoming.try_recv().is_err());
 59	
 60	    // B can only answer authenticated inbound Noise requests; it never pushes.
 61	    // The local JoinSet and shutdown join own every accepted connection even
 62	    // when the one bounded requester attempt fails or reaches its deadline.
 63	    let (stop, mut stopped) = tokio::sync::oneshot::channel();
 64	    let serving = async {
 65	        let mut connections = tokio::task::JoinSet::new();
 66	        loop {
 67	            tokio::select! {
 68	                accepted = listener.accept() => {
 69	                    let (stream, _) = accepted.unwrap();
 70	                    let responder = b.clone();
 71	                    connections.spawn(async move {
 72	                        if let Ok(channel) = responder.privacy_accept(stream).await {
 73	                            responder.serve_connection(channel).await;
 74	                        }
 75	                    });
 76	                }
 77	                result = connections.join_next(), if !connections.is_empty() => {
 78	                    result.unwrap().unwrap();
 79	                }
 80	                _ = &mut stopped => break,
 81	            }
 82	        }
 83	        connections.abort_all();
 84	        while let Some(result) = connections.join_next().await {
 85	            if let Err(error) = result {
 86	                assert!(error.is_cancelled());
 87	            }
 88	        }
 89	    };
 90	    let mut manifest_received = false;
 91	    let requesting = async {
 92	        let result = tokio::time::timeout(std::time::Duration::from_secs(10), async {
 93	            if retained {
 94	                let file = a.delivery.lock().unwrap().file_card(card).unwrap().clone();
 95	                let destination = file.destinations[0].clone();
 96	                let mut transfers = std::collections::HashMap::new();
 97	                loop {
 98	                    a.retry_file_step(&file, &destination, &mut transfers).await;
 99	                    manifest_received |= offers.try_recv().is_ok();
100	                    if manifest_received
101	                        && a.log.lock().unwrap().get(&original.id).unwrap().is_some()
102	                    {
103	                        break;
104	                    }
105	                    tokio::task::yield_now().await;
106	                }
107	            } else {
108	                // Immediate sends use the same bidirectional manifest protocol
109	                // and return while the recipient still awaits manual consent.
110	                a.flush_file_delivery(card).await;
111	            }
112	        })
113	        .await;
114	        let _ = stop.send(());
115	        result
116	    };
117	    let (attempt, ()) = tokio::join!(requesting, serving);
118	    attempt.expect("the real file requester must complete its manual-consent attempt");
119	    assert!(
120	        manifest_received || offers.try_recv().is_ok(),
121	        "the remote manifest was received"
122	    );
123	    assert_eq!(
124	        a.log.lock().unwrap().get(&original.id).unwrap().unwrap(),
125	        original,
126	        "the requester durably accepted the exact original reply ciphertext"
127	    );
128	    // No history query, manual emit, second payload or reverse connection may
129	    // heal reception between the raw-ciphertext witness and these assertions.
130	    let received = tokio::time::timeout(std::time::Duration::from_secs(2), incoming.recv())
131	        .await
132	        .expect("file-initiated DM acceptance must dispatch plaintext")
133	        .unwrap();
134	    assert_eq!(received.message_id, Some(reply));
135	    assert_eq!(received.text, b"reply pulled by a file requester");
136	    assert!(
137	        a.delivery
138	            .lock()
139	            .unwrap()
140	            .retry_receipts(8)
141	            .iter()
142	            .any(|receipt| {
143	                receipt.logical_id == reply
144	                    && receipt.original_event_id == original.id
145	                    && receipt.conversation
146	                        == super::conversation::account_conversation_id(
147	                            &a.account_id(),
148	                            &b.account_id(),
149	                        )
150	                    && receipt.destination.device == bp.public()
151	                    && receipt.destination.account == bp.account_id()
152	            }),
153	        "the receiving account must queue the exact original recipient receipt"
154	    );
155	}
