158	async fn clean_delivery_reconciliation_is_quiet_and_later_remote_data_advances() {
159	    let receiver_dir = tempfile::tempdir().unwrap();
160	    let source_dir = tempfile::tempdir().unwrap();
161	    let receiver_identity = DeviceIdentity::generate();
162	    let receiver_account = Account::generate();
163	    let source_identity = DeviceIdentity::generate();
164	    let source_account = Account::generate();
165	    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
166	    let receiver_proof =
167	        Announce::new_with_account(&receiver_identity, &receiver_account, "Receiver", 9);
168	    let source_proof = Announce::new_with_account(
169	        &source_identity,
170	        &source_account,
171	        "Source",
172	        listener.local_addr().unwrap().port(),
173	    );
174	    let (receiver, mut received) = node(
175	        receiver_dir.path(),
176	        receiver_identity,
177	        receiver_account,
178	        &source_proof,
179	    );
180	    let (source, _) = node(
181	        source_dir.path(),
182	        source_identity,
183	        source_account,
184	        &receiver_proof,
185	    );
186	    receiver.replace_verified_dm_pull_peers(vec![source_proof.user_id.clone()]);
187	    // Only serve inbound requests: background push/recovery must not import the
188	    // new message before the explicitly measured reconciliation owns it.
189	    let responder = source.clone();
190	    let server = tokio::spawn(async move {
191	        let mut connections = tokio::task::JoinSet::new();
192	        loop {
193	            tokio::select! {
194	                accepted = listener.accept() => {
195	                    let (stream, _) = accepted.unwrap();
196	                    let responder = responder.clone();
197	                    connections.spawn(async move {
198	                        let channel = responder.privacy_accept(stream).await.unwrap();
199	                        responder.serve_connection(channel).await;
200	                    });
201	                }
202	                result = connections.join_next(), if !connections.is_empty() => {
203	                    result.unwrap().unwrap();
204	                }
205	            }
206	        }
207	    });
208	    let result = tokio::time::timeout(std::time::Duration::from_secs(15), async {
209	        let empty = receiver.reconcile_delivery_peer(&source_proof).await;
210	        let target = receiver.account_id();
211	        let id = source
212	            .enqueue_to_account(&target, b"new data after a quiet pull", None)
213	            .await
214	            .unwrap();
215	        assert!(received.try_recv().is_err());
216	        let advanced = receiver.reconcile_delivery_peer(&source_proof).await;
217	        let message = received.try_recv().unwrap();
218	        let quiet = receiver.reconcile_delivery_peer(&source_proof).await;
219	        let relay = DeviceIdentity::generate();
220	        let relay_proof = Announce::new_post_office_with_account(
221	            &relay,
222	            &Account::generate(),
223	            "Cooling relay",
224	            9,
225	        );
226	        receiver.roster.lock().unwrap().update(
227	            &relay_proof,
228	            IpAddr::V4(Ipv4Addr::LOCALHOST),
229	            &receiver.user_id(),
230	        );
231	        assert!(receiver.relay_receive_allowed(&relay_proof.public()));
232	        // A retained failed-attempt deadline represents unresolved relay work.
233	        // A clean direct replay cannot relabel that skipped relay as quiet.
234	        receiver.record_relay_attempt(&relay_proof.public(), false);
235	        assert!(!receiver.relay_retry_due(&relay_proof.public()));
236	        let cooling = receiver.reconcile_delivery_peer(&source_proof).await;
237	        (empty, advanced, quiet, cooling, id, message.message_id)
238	    })
239	    .await;
240	    server.abort();
241	    let retired = server.await.unwrap_err();
242	    assert!(retired.is_cancelled());
243	    let (empty, advanced, quiet, cooling, id, received_id) = result.unwrap();
244	    assert_eq!(
