101	            } else {
102	                manifest.name().to_owned()
103	            },
104	            size: manifest.size(),
105	            mime: manifest.mime().to_owned(),
106	            file_conv: manifest.file_conv(),
107	            media: super::super::media_store::manifest_is_media(&manifest),
